export const PLSCADD_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/plscadd-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getPlsCaddStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(PLSCADD_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
